mapper.select:
SELECT ic.contract_id AS contract_id, ic.contract_no AS contract_no, i.insurer_name AS insurer_name, p.product_name AS product_name, ic.contract_date AS contract_date, ic.monthly_equivalent_first_premium AS monthly_equivalent_first_premium, CONCAT('FC-', LPAD(a.agent_id::text, 4, '0'), ' ', a.agent_name) AS agent_id_name, ic.current_status AS contract_status, cc.result_status AS cap_result_status, ic.data_origin AS data_origin FROM insurance_contract ic --계약 JOIN insurer i --보험회사 이름 가져와야함 ON i.insurer_id = ic.insurer_id JOIN product_offering po --상품판매 버전을 가져와서 상품 테이블 JOIN ON po.product_offering_id = ic.product_offering_id JOIN product p --상품판매 버전 id로 ON p.product_id = po.product_id JOIN agent a -- 설계사 번호 , 이름 ON a.agent_id = ic.agent_id LEFT JOIN fgc.vw_latest_cap_check cc --1200% 한도 가장 최근껄 가져옴 ON cc.contract_id = ic.contract_id AND cc.payment_stage = 'GA_TO_FC' -- mapper로 받는 매개변수가 2개 이상일 경우 condition. 을 붙여 명시
AND ic.contract_no LIKE CONCAT('%', #{condition.contractNo}, '%')
AND ic.insurer_id = #{condition.insurerId}
AND ic.product_offering_id = #{condition.productOfferingId}
AND ic.agent_id = #{condition.agentId}
AND ic.organization_id = #{condition.orgId}
AND cc.result_status = #{condition.capResultStatus}
AND ic.current_status = #{condition.currentStatus}
AND ic.contract_date >= #{condition.contractDateFrom}
AND ic.contract_date <= #{condition.contractDateTo}
ORDER BY ic.contract_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM fgc.insurance_contract ic JOIN fgc.insurer i ON i.insurer_id = ic.insurer_id JOIN fgc.product_offering po ON po.product_offering_id = ic.product_offering_id JOIN fgc.product p ON p.product_id = po.product_id JOIN fgc.agent a ON a.agent_id = ic.agent_id LEFT JOIN fgc.vw_latest_cap_check cc ON cc.contract_id = ic.contract_id AND cc.payment_stage = 'GA_TO_FC'
AND ic.contract_no LIKE CONCAT('%', #{contractNo}, '%')
AND ic.insurer_id = #{insurerId}
AND ic.product_offering_id = #{productOfferingId}
AND ic.agent_id = #{agentId}
AND ic.organization_id = #{orgId}
AND cc.result_status = #{capResultStatus}
AND ic.current_status = #{currentStatus}
AND ic.contract_date >= #{contractDateFrom}
AND ic.contract_date <= #{contractDateTo}

SELECT ic.contract_id AS contract_id, ic.contract_no AS contract_no, i.insurer_name AS insurer_name, p.product_name AS product_name, ic.contract_date AS contract_date, ic.monthly_equivalent_first_premium AS monthly_equivalent_first_premium, CONCAT('FC-', LPAD(a.agent_id::text, 4, '0'), ' ', a.agent_name) AS agent_id_name, ic.current_status AS contract_status, cc.result_status AS cap_result_status, ic.data_origin AS data_origin FROM insurance_contract ic JOIN insurer i ON i.insurer_id = ic.insurer_id JOIN product_offering po ON po.product_offering_id = ic.product_offering_id JOIN product p ON p.product_id = po.product_id JOIN agent a ON a.agent_id = ic.agent_id LEFT JOIN fgc.vw_latest_cap_check cc ON cc.contract_id = ic.contract_id AND cc.payment_stage = 'GA_TO_FC'
AND ic.contract_no LIKE CONCAT('%', #{condition.contractNo}, '%') AND ic.insurer_id = #{condition.insurerId} AND ic.product_offering_id = #{condition.productOfferingId} AND ic.agent_id = #{condition.agentId} AND ic.organization_id = #{condition.orgId} AND cc.result_status = #{condition.capResultStatus} AND ic.current_status = #{condition.currentStatus} AND ic.contract_date >= #{condition.contractDateFrom} AND ic.contract_date <= #{condition.contractDateTo}
ORDER BY ic.contract_id DESC
